package markdown

import (
	"fmt"
	"strings"
)

// Render translates a markdown string into HTML.
//
// Refactoring notes:
// The original implementation walked the input byte by byte while juggling
// several intertwined pieces of state (header level, list depth, whether a
// list item was open, whether a header had already been emitted, ...), which
// made it very hard to follow. This version keeps the same observable
// behaviour for the supported syntax, but is organised around the three
// independent ideas the parser actually uses:
//
//  1. expandEmphasis rewrites the first "__" / "_" marker pairs into
//     <strong> / <em> tags before anything else happens.
//  2. The input is split into lines.
//  3. Each line is rendered as exactly one of: a list item, a header, or a
//     paragraph. A list stays open across consecutive "* " lines and is
//     closed when a non-list line (or the end of input) is reached.
func Render(markdown string) string {
	var b strings.Builder
	inList := false

	for _, line := range strings.Split(expandEmphasis(markdown), "\n") {
		if item, ok := listItemText(line); ok {
			if !inList {
				b.WriteString("<ul>")
				inList = true
			}
			b.WriteString("<li>" + item + "</li>")
			continue
		}
		if inList {
			b.WriteString("</ul>")
			inList = false
		}
		b.WriteString(renderBlock(line))
	}

	if inList {
		b.WriteString("</ul>")
	}
	return b.String()
}

// expandEmphasis rewrites the first "__" marker pair into <strong> tags and
// the first "_" marker pair into <em> tags. The "__" pair must be handled
// first so that bold markers are not consumed by the italic pass.
func expandEmphasis(s string) string {
	s = strings.Replace(s, "__", "<strong>", 1)
	s = strings.Replace(s, "__", "</strong>", 1)
	s = strings.Replace(s, "_", "<em>", 1)
	s = strings.Replace(s, "_", "</em>", 1)
	return s
}

// listItemText reports whether line is an unordered list item, i.e. it starts
// with "*", and returns the item text with the marker (and the space after
// it) removed.
func listItemText(line string) (string, bool) {
	if !strings.HasPrefix(line, "*") {
		return "", false
	}
	return strings.TrimPrefix(strings.TrimPrefix(line, "*"), " "), true
}

// renderBlock renders a non-list line as a header if it starts with one to
// six "#", and as a paragraph otherwise. Lines with more than six leading
// hashes are not valid headers, so the hashes are kept as literal paragraph
// text.
func renderBlock(line string) string {
	level, isHeader := leadingHashes(line)
	if !isHeader || level > 6 {
		return "<p>" + line + "</p>"
	}
	text := strings.TrimPrefix(strings.TrimLeft(line, "#"), " ")
	return fmt.Sprintf("<h%d>%s</h%d>", level, text, level)
}

// leadingHashes returns the number of consecutive "#" characters at the
// start of line, and whether there is at least one.
func leadingHashes(line string) (int, bool) {
	level := 0
	for level < len(line) && line[level] == '#' {
		level++
	}
	return level, level > 0
}

